+++ b/source/transfer-relay.ts
@@ -0,0 +1,36 @@
+import type {EventEmitter} from 'node:events';
+
+const relayedEvents = ['uploadProgress', 'downloadProgress', 'error'] as const;
+
+/**
+Forward `uploadProgress`, `downloadProgress` and `error` events from `source` to `destination`.
+
+@returns A function that stops relaying. It removes only the listeners installed here and calls `onClose` once, no matter how many times it is called.
+*/
+export function relayTransfer(source: EventEmitter, destination: EventEmitter, onClose: () => void): () => void {
+	const listeners = relayedEvents.map(event => {
+		const listener = (...arguments_: unknown[]) => {
+			destination.emit(event, ...arguments_);
+		};
+
+		source.on(event, listener);
+
+		return [event, listener] as const;
+	});
+
+	let isDisposed = false;
+
+	return () => {
+		if (isDisposed) {
+			return;
+		}
+
+		isDisposed = true;
+
+		for (const [event, listener] of listeners) {
+			source.off(event, listener);
+		}
+
+		onClose();
+	};
+}
diff --git a/test/transfer-relay.ts b/test/transfer-relay.ts
new file mode 100644
index 0000000..868ae51
--- /dev/null
+++ b/test/transfer-relay.ts
@@ -0,0 +1,89 @@
+import {EventEmitter} from 'node:events';
+import test from 'ava';
+import {relayTransfer} from '../source/transfer-relay.js';
+
+test('forwards progress and error events with all arguments', t => {
+	const source = new EventEmitter();
+	const destination = new EventEmitter();
+	const received: Array<[string, unknown[]]> = [];
+
+	for (const event of ['uploadProgress', 'downloadProgress', 'error']) {
+		destination.on(event, (...arguments_: unknown[]) => {
+			received.push([event, arguments_]);
+		});
+	}
+
+	relayTransfer(source, destination, () => {});
+
+	const error = new Error('oops');
+	source.emit('uploadProgress', {percent: 0.5}, 1, 2);
+	source.emit('downloadProgress', {percent: 1});
+	source.emit('error', error, 'extra');
+
+	t.deepEqual(received, [
+		['uploadProgress', [{percent: 0.5}, 1, 2]],
+		['downloadProgress', [{percent: 1}]],
+		['error', [error, 'extra']],
+	]);
+});
+
+test('does not forward other events', t => {
+	const source = new EventEmitter();
+	const destination = new EventEmitter();
+	let called = false;
+
+	destination.on('response', () => {
+		called = true;
+	});
+
+	relayTransfer(source, destination, () => {});
+	source.emit('response', {});
+
+	t.false(called);
+});
+
+test('disposer removes only its own listeners and calls onClose once', t => {
+	const source = new EventEmitter();
+	const destination = new EventEmitter();
+	const ownListener = () => {};
+	source.on('uploadProgress', ownListener);
+	source.on('error', ownListener);
+
+	let closeCount = 0;
+	const dispose = relayTransfer(source, destination, () => {
+		closeCount++;
+	});
+
+	t.is(source.listenerCount('uploadProgress'), 2);
+
+	dispose();
+	dispose();
+
+	t.is(closeCount, 1);
+	t.deepEqual(source.listeners('uploadProgress'), [ownListener]);
+	t.deepEqual(source.listeners('error'), [ownListener]);
+	t.is(source.listenerCount('downloadProgress'), 0);
+
+	let forwarded = false;
+	destination.on('downloadProgress', () => {
+		forwarded = true;
+	});
+	source.emit('downloadProgress', {});
+	t.false(forwarded);
+});
+
+test('disposing before any events works', t => {
+	const source = new EventEmitter();
+	const destination = new EventEmitter();
+	let closeCount = 0;
+
+	const dispose = relayTransfer(source, destination, () => {
+		closeCount++;
+	});
+	dispose();
+
+	t.is(closeCount, 1);
+	t.is(source.listenerCount('uploadProgress'), 0);
+	t.is(source.listenerCount('downloadProgress'), 0);
+	t.is(source.listenerCount('error'), 0);
+});
